test_grid = globals()['test_grid']
demos = globals()['demos']
zero_rows = [9, 10, 11]
zero_cols = [14, 15, 16]

# Try to generate full grid using H transformation
def apply_h(grid, r, c):
    # H-pattern: horizontal mirror
    return grid[r][23 - c]  # Mirror across horizontal center

def apply_v(grid, r, c):
    # V-pattern: vertical mirror  
    return grid[23 - r][c]

def apply_d(grid, r, c):
    # D-pattern: diagonal
    return grid[r][23 - c]  # Sort of diagonal

# Wait, let me look at what the earlier analysis found:
# Demo 1 & 2: Shift 0 V-MIRROR: output[r][c] = input[23-r][c]
# Demo 3: Shift -1 V-MIRROR: output[r][c] = input[23-r][23-c+1] = input[23-r][c-1]

# Let me try applying these with TEST's zeros
def v_mirror_shift0(grid, r, c):
    return grid[23-r][c]

def v_mirror_shift1(grid, r, c):
    return grid[23-r][c-1]  # shift +1

def v_mirror_shiftneg1(grid, r, c):
    return grid[23-r][c+1]  # shift -1

print("V-MIRROR shift 0 at zero region:")
for r in zero_rows:
    for c in zero_cols:
        print(f"  ({r},{c}) = {v_mirror_shift0(test_grid, r, c)}")

print("\nV-MIRROR shift +1 at zero region:")
for r in zero_rows:
    for c in zero_cols:
        print(f"  ({r},{c}) = {v_mirror_shift1(test_grid, r, c)}")

